class Solution {
    public int[] findThePrefixCommonArray(int[] A, int[] B) {
        int n = A.length;
        boolean[] seenA = new boolean[n + 1];
        boolean[] seenB = new boolean[n + 1];
        int[] answer = new int[n];
        int common = 0;

        for (int i = 0; i < n; i++) {
            int left = A[i];
            int right = B[i];
            seenA[left] = true;
            seenB[right] = true;

            if (seenB[left]) {
                common++;
            }
            if (left != right && seenA[right]) {
                common++;
            }
            answer[i] = common;
        }
        return answer;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int[] findThePrefixCommonArray(int[] A, int[] B) {
        int n = A.length;
        int[] answer = new int[n];
        Set<Integer> seenA = new HashSet<>();
        Set<Integer> seenB = new HashSet<>();

        for (int i = 0; i < n; i++) {
            seenA.add(A[i]);
            seenB.add(B[i]);

            int common = 0;
            for (int value : seenA) {
                if (seenB.contains(value)) {
                    common++;
                }
            }
            answer[i] = common;
        }
        return answer;
    }
}

class Solution {
    public int[] findThePrefixCommonArray(int[] A, int[] B) {
        int n = A.length;
        int[] positionInB = new int[n + 1];
        for (int i = 0; i < n; i++) {
            positionInB[B[i]] = i;
        }

        Fenwick tree = new Fenwick(n);
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            tree.add(positionInB[A[i]], 1);
            answer[i] = tree.sum(i);
        }
        return answer;
    }

    private static class Fenwick {
        private final int[] tree;

        Fenwick(int n) {
            tree = new int[n + 1];
        }

        void add(int index, int delta) {
            for (int i = index + 1; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }

        int sum(int index) {
            int total = 0;
            for (int i = index + 1; i > 0; i -= i & -i) {
                total += tree[i];
            }
            return total;
        }
    }
}
